CREATE OR REPLACE FUNCTION app.guard_driver_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.driver_type IS DISTINCT FROM OLD.driver_type THEN
      RAISE EXCEPTION 'Driver type cannot be changed.' USING ERRCODE = '23514';
    END IF;
    IF NEW.person_id IS DISTINCT FROM OLD.person_id THEN
      RAISE EXCEPTION 'Driver person cannot be changed.' USING ERRCODE = '23514';
    END IF;
    NEW.updated_at := now();
  END IF;
  IF TG_OP = 'INSERT' AND NEW.driver_type = 'EMPLOYEE' THEN
    IF EXISTS (SELECT 1 FROM app.volunteers WHERE person_id = NEW.person_id)
       OR EXISTS (SELECT 1 FROM app.people WHERE id = NEW.person_id AND app_user_id IS NOT NULL) THEN
      RAISE EXCEPTION 'An NGO employee driver must be a separate person without a Volunteer record or login.'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.guard_fixed_driver_vehicle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  old_is_employee boolean := false;
  new_is_employee boolean := false;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.assigned_driver_id IS NOT NULL THEN
    SELECT driver_type = 'EMPLOYEE' INTO old_is_employee FROM app.drivers WHERE id = OLD.assigned_driver_id;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF coalesce(old_is_employee, false) THEN
      RAISE EXCEPTION 'Vehicle has a fixed NGO employee driver and cannot be deleted. Retire it instead.'
        USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.assigned_driver_id IS NOT NULL THEN
    SELECT driver_type = 'EMPLOYEE' INTO new_is_employee FROM app.drivers WHERE id = NEW.assigned_driver_id;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF coalesce(new_is_employee, false) THEN
      RAISE EXCEPTION 'Register the vehicle first, then link its NGO employee driver from Assign Driver.'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.assigned_driver_id IS DISTINCT FROM OLD.assigned_driver_id THEN
    IF coalesce(old_is_employee, false) THEN
      RAISE EXCEPTION 'The fixed driver-to-vehicle link cannot be changed.' USING ERRCODE = '23514';
    END IF;
    IF coalesce(new_is_employee, false) AND OLD.assigned_driver_id IS NOT NULL THEN
      RAISE EXCEPTION 'This vehicle already has a driver link.' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_employee_driver_has_vehicle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.driver_type = 'EMPLOYEE'
     AND NOT EXISTS (SELECT 1 FROM app.vehicles WHERE assigned_driver_id = NEW.id) THEN
    RAISE EXCEPTION 'An NGO employee driver must be linked to one registered vehicle.' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_vehicle_reservable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE vehicle_status text;
BEGIN
  IF NEW.vehicle_id IS NULL OR NEW.state <> 'ACTIVE' THEN RETURN NEW; END IF;
  SELECT status INTO vehicle_status FROM app.vehicles WHERE id = NEW.vehicle_id FOR UPDATE;
  IF vehicle_status IS DISTINCT FROM 'ACTIVE' THEN
    RAISE EXCEPTION 'Vehicle is not active' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM app.vehicle_unavailability
    WHERE vehicle_id = NEW.vehicle_id
      AND tstzrange(starts_at, ends_at, '[)') && tstzrange(NEW.starts_at, NEW.ends_at, '[)')
  ) THEN
    RAISE EXCEPTION 'Vehicle is unavailable during reservation' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_vehicle_downtime_available()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM 1 FROM app.vehicles WHERE id = NEW.vehicle_id FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM app.resource_reservations
    WHERE vehicle_id = NEW.vehicle_id AND state = 'ACTIVE'
      AND during && tstzrange(NEW.starts_at, NEW.ends_at, '[)')
  ) THEN
    RAISE EXCEPTION 'Vehicle has an active reservation during downtime' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_vehicle_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM app.resource_reservations
    WHERE vehicle_id = NEW.id AND state = 'ACTIVE' AND ends_at > now()
  ) THEN
    RAISE EXCEPTION 'Release active vehicle reservations before changing status'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$
